package com.example.smartpantrymanager.ui; import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import com.example.smartpantrymanager.*;import com.example.smartpantrymanager.data.*; public class PantryActivity extends Activity { DatabaseHelper db; LinearLayout list; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_pantry);db=new DatabaseHelper(this);list=findViewById(R.id.pantryList);findViewById(R.id.btnAdd).setOnClickListener(v->startActivity(new Intent(this,AddEditPantryActivity.class)));} protected void onResume(){super.onResume();render();} void render(){list.removeAllViews();for(var p:db.all()){TextView t=new TextView(this);t.setText(p.name+" — "+p.quantity+" "+p.unit);t.setTextSize(18);t.setPadding(16,16,16,16);t.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(p.name).setMessage("Quantity: "+p.quantity+" "+p.unit).setPositiveButton("Delete",(d,w)->{db.delete(p.id);render();}).setNegativeButton("Close",null).show());list.addView(t);}} }